class CosmosQuery
{
    // EF Core 9 removed synchronous Cosmos APIs — all queries must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL still works; discriminator property kept as "Discriminator"
        // via HasDiscriminator() override in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Sync .ToList() no longer compiles against Cosmos provider in EF Core 9.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

